-- The client's 4D & Toto tools (README-4d-toto-tools.md) as Components, so
-- the content team can place them on /4d-toto/prizes and
-- /4d-toto/lucky-number-generator with a "component" block. Adapted from the
-- client's static build: heading, starting tab and small print are
-- settings; colours come from the site's theme. Code is base64 so nothing
-- needs SQL escaping. Added only if no component has the name yet, so an
-- edited copy is never overwritten.

INSERT INTO components (name, description, html, css, js, settings)
SELECT '4D & Toto Prize Calculator', 'Works out a 4D or Toto prize from the bet and the numbers matched. For /4d-toto/prizes.',
    CONVERT(FROM_BASE64('') USING utf8mb4),
    CONVERT(FROM_BASE64('') USING utf8mb4),
    CONVERT(FROM_BASE64('') USING utf8mb4),
    CONVERT(FROM_BASE64('') USING utf8mb4)
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM components WHERE name = '4D & Toto Prize Calculator');

INSERT INTO component_revisions (component_id, snapshot)
SELECT c.id, CONVERT(FROM_BASE64('') USING utf8mb4)
FROM components c
WHERE c.name = '4D & Toto Prize Calculator' AND NOT EXISTS (SELECT 1 FROM component_revisions r WHERE r.component_id = c.id);

INSERT INTO components (name, description, html, css, js, settings)
SELECT 'Lucky Number Generator', 'Picks random Toto (6 to 12 numbers) or 4D numbers on the visitor''s device. For /4d-toto/lucky-number-generator.',
    CONVERT(FROM_BASE64('') USING utf8mb4),
    CONVERT(FROM_BASE64('') USING utf8mb4),
    CONVERT(FROM_BASE64('') USING utf8mb4),
    CONVERT(FROM_BASE64('') USING utf8mb4)
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM components WHERE name = 'Lucky Number Generator');

INSERT INTO component_revisions (component_id, snapshot)
SELECT c.id, CONVERT(FROM_BASE64('') USING utf8mb4)
FROM components c
WHERE c.name = 'Lucky Number Generator' AND NOT EXISTS (SELECT 1 FROM component_revisions r WHERE r.component_id = c.id);
